effect.shader:
void main(){
vec2 uv=acScreenNorm,p=uv-0.5,q=uv; vec4 src=texture2DCv(inputImg.texture,uv),dst=src;
const float c=2.0,m=4.0; float k=clamp(intensity,0.0,1.0),t=phase*6.2831853;
if(c<0.5){
if(m<0.5){float l=dot(src.rgb,vec3(.2126,.7152,.0722));dst.rgb=mix(vec3(l*.38,l*.88,l*1.05),vec3(l*1.18,l*.72,l*.28),smoothstep(.35,.75,l));}
else if(m<1.5){vec2 d=vec2(.003+.012*k,0);dst.r=texture2DCv(inputImg.texture,clamp(uv+d,0.0,1.0)).r;dst.b=texture2DCv(inputImg.texture,clamp(uv-d,0.0,1.0)).b;dst.g=src.g*1.08;}
else if(m<2.5){float l=dot(src.rgb,vec3(.3,.59,.11));dst.rgb=vec3(smoothstep(.2,.9,l),smoothstep(.55,1.,l),1.-smoothstep(.1,.8,l));}
else if(m<3.5){dst.rgb=floor(pow(max(src.rgb,vec3(0.0)),vec3(.82))*(4.0+8.0*k))/(4.0+8.0*k);}
else {float l=dot(src.rgb,vec3(.299,.587,.114));dst.rgb=mix(src.bgr,vec3(l*1.3,l*.72,1.-l*.55),.62*k);}
} else if(c<1.5){
vec2 d=(m<.5?vec2(.012+.035*k,0):m<1.5?normalize(p+vec2(.0001))*(.006+.025*k):m<2.5?vec2(.012,.012):m<3.5?normalize(vec2(cos(t),sin(t)))*(.012+.04*k):vec2(.007+.018*k,0));
dst=(src+texture2DCv(inputImg.texture,clamp(uv+d,0.,1.))+texture2DCv(inputImg.texture,clamp(uv-d,0.,1.))+texture2DCv(inputImg.texture,clamp(uv+d*2.,0.,1.))+texture2DCv(inputImg.texture,clamp(uv-d*2.,0.,1.)))/5.;
if(m>3.5)dst.rgb+=max(dst.rgb-src.rgb,0.)*.8;
} else if(c<2.5){
if(m<.5)q=uv+vec2(sin((uv.y*scale+t)*6.28),cos((uv.x*scale-t)*6.28))*.025*k;
else if(m<1.5)q=uv+normalize(p+vec2(.0001))*sin(length(p)*scale*30.-t)*.035*k;
else if(m<2.5)q=.5+p*(1.+sin(p.y*scale*8.+t)*.22*k);
else if(m<3.5)q=uv+vec2(sin(uv.y*45.+t),cos(uv.x*37.-t))*.012*k;else {float a=atan(p.y,p.x)+k*.7*(1.-length(p)*2.);q=.5+length(p)*vec2(cos(a),sin(a));}
dst=texture2DCv(inputImg.texture,clamp(q,0.,1.));
} else if(c<3.5){
float v=m<.5?sin(p.x*9.+t)+sin(p.y*13.-t):m<1.5?sin((p.x+p.y)*22.+t)*cos((p.x-p.y)*17.-t):m<2.5?sin(p.y*55.+sin(p.x*8.+t)*5.):m<3.5?sin(length(fract(p*scale)-.5)*38.-t):sin(length(p)*70.-t*2.);
vec3 col=.5+.5*cos(vec3(0.,2.1,4.2)+v*2.2+t*.15);dst.rgb=mix(src.rgb,col,.25+.55*k*smoothstep(-.3,.8,v));
} else if(c<4.5){
float z=(m<.5?abs(p.x):m<1.5?p.x*p.y:m<2.5?sin(p.x*8.+t)*.12:m<3.5?sin(length(p)*20.-t)*.12:length(p)) * k;
if(m<.5)q=.5+vec2(p.x*(1.-abs(p.y)*.35*k),p.y+sign(p.x)*z*.18);else if(m<1.5)q=.5+p/(1.+z*.6);else if(m<2.5)q=.5+vec2(atan(p.x,.55)/1.1,p.y)*(1.+z*.2);else if(m<3.5)q=.5+p+vec2(0.,z*.22);else q=.5+p*(.82+.18*cos(t))+vec2(sin(t),cos(t))*.04*k;
dst=texture2DCv(inputImg.texture,clamp(q,0.,1.));dst.rgb*=.72+.45*clamp(1.-z,0.,1.);
} else if(c<5.5){
vec2 px=vec2(1./720.,1./720.);float l=dot(src.rgb,vec3(.299,.587,.114)),lx=dot(texture2DCv(inputImg.texture,uv+vec2(px.x,0)).rgb,vec3(.299,.587,.114)),ly=dot(texture2DCv(inputImg.texture,uv+vec2(0,px.y)).rgb,vec3(.299,.587,.114));float e=length(vec2(l-lx,l-ly))*(8.+24.*k);float hatch=step(.62,fract((p.x*(m+2.)+p.y*(6.-m))*scale*9.));dst.rgb=m<1.5?mix(src.rgb,vec3(e, e*.65,1.2*e),k):m<2.5?mix(src.rgb,vec3(hatch*l),k*.7):m<3.5?src.rgb+vec3(e*1.5,e*.55,e*.2):m<4.5?mix(src.rgb,vec3(step(.42,l))*hatch,k):mix(src.rgb,vec3(e)*vec3(1.,.8,.35),k);
} else if(c<6.5){
float decay=exp(-max(0.,phase)*3.2),b=sin(phase*18.)*decay*k;if(m<.5)q=uv+vec2(0.,b*.12);else if(m<1.5)q=.5+p/(1.+b*.45);else if(m<2.5){float a=b*.8;q=.5+mat2(cos(a),-sin(a),sin(a),cos(a))*p;}else if(m<3.5)q=uv+vec2(sin(t)*.08*k*(1.-abs(p.y)),0.);else q=.5+p/(.72+.28*smoothstep(0.,1.,phase)+b*.18);dst=texture2DCv(inputImg.texture,clamp(q,0.,1.));
} else if(c<7.5){
float l=dot(src.rgb,vec3(.299,.587,.114)),lr=dot(texture2DCv(inputImg.texture,uv+vec2(1./720.,0.)).rgb,vec3(.299,.587,.114)),ld=dot(texture2DCv(inputImg.texture,uv+vec2(0.,1./720.)).rgb,vec3(.299,.587,.114)),n=fract(sin(dot(floor(uv*scale*18.),vec2(12.9898,78.233)))*43758.5453);float a=m<.5?smoothstep(.5-k*.35,.5+k*.12,l):m<1.5?smoothstep(.58,.2,length(p)):m<2.5?smoothstep(.01,.12,length(vec2(l-lr,l-ld))):m<3.5?smoothstep(.45-k*.35,.55+k*.15,n):smoothstep(.55-k*.3,.95,l);dst.a*=a;
} else {
if(m<.5){float scan=.82+.18*sin(uv.y*900.+t);dst.rgb=src.rgb*scan;}
else if(m<1.5){float scan=step(.55,fract(uv.y*scale*35.+phase));dst.rgb=mix(src.rgb,vec3(src.g,src.b,src.r),scan*.35*k);}
else if(m<2.5){float n=fract(sin(dot(uv+phase,vec2(12.9898,78.233)))*43758.5453);dst.rgb=src.rgb*(.88+.22*n)+vec3(.04,.025,0.)*k;}
else if(m<3.5){vec2 g=floor(uv*(40.+scale*12.))/(40.+scale*12.);dst=texture2DCv(inputImg.texture,g+vec2(sin(g.y*80.+t)*.015*k,0.));}
else {vec2 d=vec2(.004+.012*k,0);dst=vec4(texture2DCv(inputImg.texture,uv+d).r,src.g,texture2DCv(inputImg.texture,uv-d).b,src.a);dst.rgb*=.85+.15*sin(uv.y*700.);}
}
gl_FragColor=mix(src,dst,clamp(mixAmount,0.,1.));
}
